  "ubicacion": {
    "direccion_objetivo": "refugio de Monte Azul",
    "referencias_acceso": null,
    "localidad_detectada": "Monte Azul",
    "estado_ruta": null,
    "estado_ubicacion": "PARCIAL"
  },
  "requerimientos_operativos": [],
